 const layer=$('timing-line');layer.replaceChildren();const ref=integrationState.startFinish,p=items.find(p=>p.id===ref?.pieceId);if(!p)return;const d=defOf(p),q=d.parameters;if(!d.geometry.lanePaths.length)return;
