 for(const l of [...g.lanePaths,...(g.alternateLanePaths||[]).map(route=>({d:route.switchSvgPath}))])body+=G.path(l.d,'none',print?'#bbb':'#aeb5b7',8)+G.path(l.d,'none',print?'#333':'#14181d',2.8);return body;
