function transform(p){return`translate(${p.x} ${p.y}) rotate(${p.angle}) scale(1 ${p.flip?-1:1})`;}
function guideSize(g){return Number(g.lengthMm.toFixed(1))+' × '+Number(g.widthMm.toFixed(1))+' mm';}
