function openSpaceGuide(){finishDrag(true);const g=spaceGuide||{lengthMm:3000,widthMm:1500,locked:false};$('guide-length').value=Number(g.lengthMm.toFixed(2));$('guide-width').value=Number(g.widthMm.toFixed(2));$('guide-lock').checked=g.locked;$('guide-scale').value=100;$('guide-error').textContent='';$('guide-remove').hidden=!spaceGuide;$('space-guide-dialog').showModal();}
$('space-guide-edit').onclick=openSpaceGuide;
$('space-guide-lock').onclick=()=>{if(!spaceGuide)return;finishDrag(true);checkpoint();spaceGuide={...spaceGuide,locked:!spaceGuide.locked};refresh();say(spaceGuide.locked?'Space guide locked. Build freely over it.':'Space guide unlocked. Drag its area or resize handle.');};
$('guide-apply-scale').onclick=()=>{try{const factor=Number($('guide-scale').value)/100;if(!Number.isFinite(factor)||factor<=0)throw Error('Enter a positive scale percentage.');const g=F.validateSpaceGuide({x:0,y:0,lengthMm:Number($('guide-length').value)*factor,widthMm:Number($('guide-width').value)*factor,locked:false});$('guide-length').value=Number(g.lengthMm.toFixed(2));$('guide-width').value=Number(g.widthMm.toFixed(2));$('guide-scale').value=100;$('guide-error').textContent='';}catch(e){$('guide-error').textContent=e.message;}};
