function familyDraft(){const f=$('piece-form').elements;return CP.curveParameters({innerRadiusMm:Number(f.baseRadiusMm.value),widthMm:Number(f.widthMm.value),angleDeg:Number(f.angleDeg.value),laneCount:Number(f.laneCount.value),laneSpacingMm:Number(f.laneSpacingMm.value)});}
function matchingCurve(){const f=$('piece-form').elements;return f.type.value==='curve'&&f.curveMode.value==='family';}
function updateCurveHelper(){
 const f=$('piece-form').elements,matching=matchingCurve();$('curve-helper').hidden=f.type.value!=='curve';$('curve-family-fields').hidden=!matching;f.baseRadiusMm.disabled=!matching;f.radiusNumber.disabled=!matching;f.innerRadiusMm.readOnly=matching;$('curve-family-preview').hidden=!matching;
 if(!matching)return;
 const base=familyDraft(),selected=Number(f.radiusNumber.value),p=CP.curveParameters(base,selected);f.innerRadiusMm.value=p.innerRadiusMm;
 if(/^My (straight|curve)$/.test(f.name.value)||/^R[1-8] curve ·/.test(f.name.value))f.name.value='R'+selected+' curve · '+p.angleDeg+'°';
 const count=Math.max(4,selected),rows=[],paths=[],extent=base.innerRadiusMm+count*base.widthMm;
 for(let n=1;n<=count;n++){const r=base.innerRadiusMm+(n-1)*base.widthMm,shape=G.derive({...base,innerRadiusMm:r,angleDeg:90});paths.push(G.path(shape.outlineSvgPath,n===selected?'#e5484d':'#303a46','#9da9b8',2));paths.push(`<text x="${(r+base.widthMm/2)*.707}" y="${-(r+base.widthMm/2)*.707}" fill="white" text-anchor="middle" font-size="${extent/28}">R${n}</text>`);rows.push(`<tr${n===selected?' class="active"':''}><td>R${n}</td><td>${+r.toFixed(2)}</td><td>${+(r+base.widthMm).toFixed(2)}</td></tr>`);}
 $('curve-family-diagram').setAttribute('viewBox',`-20 ${-extent-20} ${extent+40} ${extent+40}`);$('curve-family-diagram').innerHTML=paths.join('');$('curve-family-table').innerHTML='<table><thead><tr><th>Radius</th><th>Inner edge · mm</th><th>Outer edge · mm</th></tr></thead><tbody>'+rows.join('')+'</tbody></table>';
 const gap=base.widthMm-(base.laneCount-1)*base.laneSpacingMm,whole=360/base.angleDeg;$('curve-family-note').textContent=`Nesting diagram shows 90° for clarity. Selected piece: ${base.angleDeg}°; ${Number.isInteger(whole)?whole+' pieces make a full circle':'this angle does not divide a full circle evenly'}. Slots across the join between radii: ${+gap.toFixed(2)} mm${Math.abs(gap-base.laneSpacingMm)>.01?' (different from the '+base.laneSpacingMm+' mm spacing within a piece)':''}. Settings are remembered for this pack. Existing pieces keep their dimensions.`;
}
function formDraft(){const f=$('piece-form').elements,isSwitch=f.type.value.startsWith('lane-'),p={type:isSwitch?'straight':f.type.value,widthMm:Number(f.widthMm.value)};if(isSwitch){p.laneChange=f.type.value.slice(5);p.switchStartMm=Number(f.switchStartMm.value);p.switchEndMm=Number(f.switchEndMm.value);}if(p.type.startsWith('straight'))p.lengthMm=Number(f.lengthMm.value);else{p.innerRadiusMm=Number(f.innerRadiusMm.value);p.angleDeg=Number(f.angleDeg.value);}if(p.type.endsWith('border'))p.side=f.side.value;else{p.laneCount=isSwitch?2:Number(f.laneCount.value);p.laneSpacingMm=Number(f.laneSpacingMm.value);}return F.validateDefinition({id:'custom:preview',name:f.name.value,pack:activePack().name,family:f.family.value,parameters:p,color:f.color.value,status:'user-defined'});}
function updateCustom(){const f=$('piece-form').elements,curve=f.type.value.startsWith('curve'),border=f.type.value.endsWith('border'),isSwitch=f.type.value.startsWith('lane-');if(isSwitch)f.laneCount.value=2;for(const [field,show]of [['length',!curve],['radius',curve],['angle',curve],['lanes',!border&&!isSwitch],['spacing',!border],['side',border],['switch-start',isSwitch],['switch-end',isSwitch]]){const el=document.querySelector(`[data-field="${field}"]`);el.hidden=!show;for(const input of el.querySelectorAll('input,select'))input.disabled=!show;}try{updateCurveHelper();customDraft=formDraft();const b=customDraft.geometry.boundsMm;$('custom-preview').setAttribute('viewBox',`${b[0]-25} ${b[1]-25} ${b[2]+50} ${b[3]+50}`);$('custom-preview').innerHTML=drawBody(customDraft);$('custom-summary').textContent=customDraft.geometry.lanePaths.length?'Slot lengths: '+customDraft.geometry.lanePaths.map(l=>l.lengthMm.toFixed(1)+' mm').join(' / '):'Border footprint only. Adds no road or lane length.';if(customDraft.geometry.alternateLanePaths){$('custom-summary').textContent+=' · Change routes: '+customDraft.geometry.alternateLanePaths.map(r=>r.lengthMm.toFixed(1)+' mm').join(' / ')+'. Preview and circuit totals use the straight-through lanes. These curves approximate your measured switch.';}$('custom-error').textContent='';$('create-piece').disabled=false;}catch(e){customDraft=null;$('custom-error').textContent=e.message;$('custom-summary').textContent='Adjust the measurements to create a valid piece.';$('custom-preview').replaceChildren();$('create-piece').disabled=true;}}
function openCustom(from){customToBuilder=document.body.dataset.section==='builder';$('create-piece').textContent=customToBuilder?'Create & add to track':'Add piece to pack';$('piece-pack-name').textContent='Adding to '+activePack().name;const form=$('piece-form');form.reset();const f=form.elements;if(!from&&activePack().curveFamily){const base=activePack().curveFamily;for(const key of ['widthMm','angleDeg','laneCount','laneSpacingMm'])f[key].value=base[key];f.baseRadiusMm.value=base.innerRadiusMm;}if(from){f.curveMode.value='independent';f.name.value=from.name+' — custom';for(const[k,v]of Object.entries(from.parameters))if(f[k])f[k].value=v;if(from.parameters.laneChange)f.type.value='lane-'+from.parameters.laneChange;f.family.value=from.family;f.color.value=from.color;}else f.family.value='custom';$('piece-dialog').showModal();updateCustom();}
