function printReport(raw=layout()){const returnFocus=document.activeElement,oldDocumentTitle=document.title;stop();const model=XM.build(raw),{pieces:items,definitions:defs,title,network}=model,defOf=p=>defs[p.definitionId],inventory=()=>model.inventory,s=model.summary,b=s.bounds,report=$('print-report');document.title=title+' — Track report';const scene=items.map(p=>`<g transform="${transform(p)}">${drawBody(defOf(p),true)}</g>`).join('');report.innerHTML=`<div class="report-tools"><button id="report-back" class="btn">← Back</button><button id="report-print" class="btn primary">Print / Save as PDF</button><span>Choose your browser’s Save as PDF destination.</span></div><h1>${E(title||'Untitled circuit')}</h1><p>SlotForge Track Builder · planning reference · ${new Date().toLocaleDateString()}</p><div class="print-meta"><span><b>${s.roads}</b> road pieces · <b>${s.borders}</b> borders · <b>${s.references}</b> references</span><span>Track centreline: <b>${meters(s.length)}</b></span><span>Approx. footprint: <b>${items.length?Math.ceil(b[2])+' × '+Math.ceil(b[3])+' mm':'—'}</b></span></div><svg xmlns="${NS}" viewBox="${b[0]-70} ${b[1]-70} ${b[2]+140} ${b[3]+140}">${scene}</svg><p>${items.some(p=>defOf(p).parameters.laneChange)?'Lane changers use straight-through routes for these totals. ':''}${network.closed?network.routes.map((r,i)=>`Lane ${i+1}: ${meters(r.lengthMm)}`).join(' · '):E(network.reason)+' Per-lane circuit lengths unavailable.'}</p><p>Nominal or user-entered measurements. Check actual track dimensions before building. Footprint includes placed borders; overlaps, vertical clearance and unplaced accessories are not checked. Diagram is fitted to page, not printed at 1:1 scale.</p><section class="print-parts"><h2>Parts inventory</h2><table><thead><tr><th>Product code</th><th>Piece</th><th>Track pack</th><th>Quantity</th><th>Centreline / piece · mm</th></tr></thead><tbody>${inventory().map(({d,count})=>`<tr><td>${E(d.sku||'Custom')}</td><td>${E(d.name)}</td><td>${E(d.pack)}</td><td>${count}</td><td>${d.parameters.type==='reference'?'Unknown':d.parameters.type.endsWith('border')?'Border':d.geometry.centrelineLengthMm.toFixed(1)}</td></tr>`).join('')}</tbody></table><p>Quantities count placed physical primitives, not retail multipacks. Reference artwork has an approximate display size, contributes no calculated length and may depict an assembly rather than one physical component.</p></section>`;document.body.classList.add("print-preview");for(const child of document.body.children)if(child!==report)child.inert=true;report.setAttribute("role","dialog");report.setAttribute("aria-label","Printable track report");$("report-back").focus();$("report-back").onclick=()=>{document.body.classList.remove("print-preview");for(const child of document.body.children)child.inert=false;document.title=oldDocumentTitle;if(returnFocus?.isConnected)returnFocus.focus();};$("report-print").onclick=()=>window.print();}
